import json
data = json.load(open('batch_0004.json', encoding='utf-8'))

def looks_mojibake(s):
    return s and (s.count('ã')>3 or any(ord(c) in range(0x80,0xA0) for c in s))

def fix_utf8_in_latin1(s):
    cur = s
    for _ in range(4):
        try:
            nxt = cur.encode('latin-1').decode('utf-8', errors='strict')
        except UnicodeDecodeError:
            if cur.count('ã') > 5:
                try:
                    nxt = cur.encode('latin-1').decode('utf-8', errors='ignore')
                except Exception:
                    break
            else:
                break
        except Exception:
            break
        if nxt == cur:
            break
        cur = nxt
    return cur

def fix_sjis_in_latin1(s):
    try:
        return s.encode('latin-1').decode('cp932', errors='ignore')
    except Exception:
        return s

def fix(s):
    if not s: return s
    f1 = fix_utf8_in_latin1(s)
    if f1 != s and not looks_mojibake(f1):
        return f1
    # try shift-jis route on original
    f2 = fix_sjis_in_latin1(s)
    if f2 != s:
        return f2
    return f1 if f1!=s else s

count=0
for item in data:
    for k in ['title','desc','body']:
        if k in item and item[k]:
            orig = item[k]
            fixed = fix(orig)
            if fixed != orig:
                item[k] = fixed
                count+=1
print('fixed fields:', count)
json.dump(data, open('../batch_0004_clean.json','w',encoding='utf-8'), ensure_ascii=False, indent=1)
"
